const rows = items.map(i => i.json);
const byBrand = {};
for (const row of rows) {
  if (!byBrand[row.brand_name]) byBrand[row.brand_name] = { hooks: new Set(), angles: new Set(), types: new Set(), stages: new Set(), count: 0 };
  byBrand[row.brand_name].count++;
  if (row.hook) byBrand[row.brand_name].hooks.add(row.hook);
  if (row.core_angle) byBrand[row.brand_name].angles.add(row.core_angle);
  if (row.ad_type) byBrand[row.brand_name].types.add(row.ad_type);
  if (row.funnel_stage) byBrand[row.brand_name].stages.add(row.funnel_stage);
}
const weekStart = new Date(Date.now()-7*24*60*60*1000).toISOString().split('T')[0];
return Object.entries(byBrand).map(([brand, data]) => ({
  json: {
    brand_name: brand,
    week_start: weekStart,
    new_ad_count: data.count,
    new_hooks: [...data.hooks].slice(0,5),
    new_angles: [...data.angles].slice(0,5),
    summary_prompt: brand + ' ran ' + data.count + ' new ads this week. Types: ' + [...data.types].join(', ') + '. Stages: ' + [...data.stages].join(', ') + '. Top hooks: ' + [...data.hooks].slice(0,3).join(' | ') + '. Write a 2-sentence strategic summary of what they are testing.'
  }
}));
